			tool: event.toolName,
			is_error: event.isError,
			subagent: !primary,
			...(event.isError ? { error_message: toolErrorText(event.result) } : {}),
		});
		if (!run) return;
		run.toolCalls += 1;
		if (event.toolName === "subagent") run.subagentCalls += 1;
	});

