			$ai_error: message.stopReason === "error" ? errorText(message.errorMessage) : undefined,
			$ai_stop_reason: message.stopReason,
			subagent: !primary,
		});
		requestStartedAt = undefined;
		httpStatus = undefined;
		if (run) run.stopReason = message.stopReason;
	});

